212	// DownloaderStoreConfig is the config that can restore the downloader.
213	type DownloaderStoreConfig struct {
214		FirstLoad bool `json:"-"` // FirstLoad is the flag that the config is first time init and not from store
215	
216		DownloadDir                string                 `json:"downloadDir"`    // DownloadDir is the default directory to save the downloaded files
217		MaxRunning                 int                    `json:"maxRunning"`     // MaxRunning is the max running download count
218		ProtocolConfig             map[string]any         `json:"protocolConfig"` // ProtocolConfig is special config for each protocol
219		GithubMirror               *GithubMirrorConfig    `json:"githubMirror"`
220		Extra                      map[string]any         `json:"extra"`
221		Proxy                      *DownloaderProxyConfig `json:"proxy"`
222		Webhook                    *WebhookConfig         `json:"webhook"`                    // Webhook is the webhook configuration
223		Script                     *ScriptConfig          `json:"script"`                     // Script is the script execution configuration
224		AutoTorrent                *AutoTorrentConfig     `json:"autoTorrent"`                // AutoTorrent is the auto torrent task creation configuration
225		Archive                    *ArchiveConfig         `json:"archive"`                    // Archive is the archive extraction configuration
226		Categories                 []*DownloadCategory    `json:"categories"`                 // Categories is the download directory category configuration
227		AutoCategorize             *bool                  `json:"autoCategorize,omitempty"`   // AutoCategorize routes downloads to category directories by file extension; unset defaults to disabled
228		API                        *APIServerConfig       `json:"api"`                        // API is the optional REST server configuration
229		AutoStartTasks             bool                   `json:"autoStartTasks"`             // AutoStartTasks continues all unfinished tasks when the backend starts
230		AutoDeleteMissingFileTasks bool                   `json:"autoDeleteMissingFileTasks"` // AutoDeleteMissingFileTasks enables automatic deletion of tasks with missing files
231	}
232	
233	func (cfg *DownloaderStoreConfig) Init() *DownloaderStoreConfig {
234		if cfg.MaxRunning == 0 {
235			cfg.MaxRunning = 5
236		}
237		if cfg.ProtocolConfig == nil {
238			cfg.ProtocolConfig = make(map[string]any)
239		}
240		if cfg.GithubMirror == nil {
241			cfg.GithubMirror = DefaultGithubMirrorConfig()
242		}
243		if cfg.Proxy == nil {
244			cfg.Proxy = &DownloaderProxyConfig{}
245		}
246		if cfg.Webhook == nil {
247			cfg.Webhook = &WebhookConfig{}
248		}
249		if cfg.Script == nil {
250			cfg.Script = &ScriptConfig{}
251		}
252		if cfg.AutoTorrent == nil {
253			cfg.AutoTorrent = &AutoTorrentConfig{
254				Enable:              false,
255				DeleteAfterDownload: false,
256			}
257		}
258		if cfg.Archive == nil {
259			cfg.Archive = &ArchiveConfig{
260				AutoExtract:        false,
261				DeleteAfterExtract: false,
262			}
263		}
264		// Seed the built-in categories for deployments that never run the flutter
265		// startup flow, e.g. headless api servers.
266		if len(cfg.Categories) == 0 && cfg.DownloadDir != "" {
267			cfg.Categories = []*DownloadCategory{
268				builtinSeedCategory("categoryMusic", "Music", cfg.DownloadDir),
269				builtinSeedCategory("categoryVideo", "Video", cfg.DownloadDir),
270				builtinSeedCategory("categoryDocument", "Document", cfg.DownloadDir),
271				builtinSeedCategory("categoryProgram", "Program", cfg.DownloadDir),
272			}
273		}
274		return cfg
275	}
276	
277	// builtinCategoryExtensions mirrors the flutter side
278	// kDefaultCategoryExtensions, keep both maps in sync.
279	var builtinCategoryExtensions = map[string][]string{
280		"categoryProgram":  {"exe", "msi", "msix", "apk", "dmg", "deb", "rpm", "pkg", "appimage"},
281		"categoryVideo":    {"mp4", "mkv", "avi", "mov", "wmv", "flv", "webm", "m4v", "mpg", "mpeg", "3gp"},
282		"categoryMusic":    {"mp3", "flac", "wav", "aac", "ogg", "m4a", "wma", "ape"},
283		"categoryDocument": {"pdf", "doc", "docx", "xls", "xlsx", "ppt", "pptx", "txt", "md", "csv", "epub", "rtf"},
284	}
285	
286	func builtinSeedCategory(nameKey, name, downloadDir string) *DownloadCategory {
287		return &DownloadCategory{
288			Name:       "",
289			Path:       filepath.Join(downloadDir, name),
290			NameKey:    nameKey,
291			IsBuiltIn:  true,
292			Extensions: append([]string(nil), builtinCategoryExtensions[nameKey]...),
293		}
294	}
295	
296	// MigrateLegacyExtraCategories moves the extra.downloadCategories list written
297	// by v2.0.0-beta builds into the top level categories field and clears the
298	// legacy key. The legacy list predates extension based routing, so built-in
299	// entries regain their default extension lists from their name key, while user
300	// created folders keep their empty list until edited in settings. It reports
301	// whether the config changed so the caller can persist the cleared key.
302	func (cfg *DownloaderStoreConfig) MigrateLegacyExtraCategories() bool {
303		if len(cfg.Categories) > 0 || cfg.Extra == nil {
304			return false
305		}
306		raw, ok := cfg.Extra["downloadCategories"]
307		if !ok {
308			return false
309		}
310		data, err := json.Marshal(raw)
311		if err != nil {
312			return false
313		}
314		var legacy []*DownloadCategory
315		if err := json.Unmarshal(data, &legacy); err != nil {
316			return false
317		}
318		categories := make([]*DownloadCategory, 0, len(legacy))
319		for _, category := range legacy {
320			if category == nil {
321				continue
322			}
323			if extensions, exist := builtinCategoryExtensions[category.NameKey]; exist && len(category.Extensions) == 0 {
324				category.Extensions = append([]string(nil), extensions...)
325			}
326			categories = append(categories, category)
327		}
328		if len(categories) == 0 {
329			return false
330		}
331		cfg.Categories = categories
332		delete(cfg.Extra, "downloadCategories")
333		return true
334	}
335	
336	// AutoCategorizeEnabled reports whether downloads are routed to category
337	// directories by file extension. The switch is optional: an unset value keeps
338	// the feature off, so an older config that never saved the field stays off.
339	func (cfg *DownloaderStoreConfig) AutoCategorizeEnabled() bool {
340		return cfg.AutoCategorize != nil && *cfg.AutoCategorize
341	}
342	
343	func (cfg *DownloaderStoreConfig) Merge(beforeCfg *DownloaderStoreConfig) *DownloaderStoreConfig {
344		if beforeCfg == nil {
345			return cfg
346		}
347		if cfg.DownloadDir == "" {
348			cfg.DownloadDir = beforeCfg.DownloadDir
349		}
350		if cfg.MaxRunning == 0 {
351			cfg.MaxRunning = beforeCfg.MaxRunning
352		}
353		if cfg.ProtocolConfig == nil {
354			cfg.ProtocolConfig = beforeCfg.ProtocolConfig
355		}
356		if cfg.Extra == nil {
357			cfg.Extra = beforeCfg.Extra
358		}
359		if cfg.GithubMirror == nil {
360			cfg.GithubMirror = beforeCfg.GithubMirror
361		}
362		if cfg.Proxy == nil {
363			cfg.Proxy = beforeCfg.Proxy
364		}
365		if cfg.Webhook == nil {
366			cfg.Webhook = beforeCfg.Webhook
367		}
368		if cfg.Script == nil {
369			cfg.Script = beforeCfg.Script
370		}
371		if cfg.AutoTorrent == nil {
372			cfg.AutoTorrent = beforeCfg.AutoTorrent
373		}
374		if cfg.Archive == nil {
375			cfg.Archive = beforeCfg.Archive
376		}
377		if cfg.Categories == nil {
378			cfg.Categories = beforeCfg.Categories
379		}
380		if cfg.AutoCategorize == nil {
381			cfg.AutoCategorize = beforeCfg.AutoCategorize
382		}
383		if cfg.API == nil {
384			cfg.API = beforeCfg.API
385		}
386		return cfg
387	}
