170	}
171	
172	func ParseReqExtra[E any](req *Request) error {
173		if req.Extra == nil {
174			return nil
175		}
176		if _, ok := req.Extra.(*E); ok {
177			return nil
178		}
179		var t E
180		if err := util.MapToStruct(req.Extra, &t); err != nil {
181			return err
182		}
183		req.Extra = &t
184		return nil
185	}
186	
187	func ParseOptExtra[E any](opts *Options) error {
188		if opts.Extra == nil {
189			return nil
190		}
191		if _, ok := opts.Extra.(*E); ok {
192			return nil
193		}
194		var t E
195		if err := util.MapToStruct(opts.Extra, &t); err != nil {
196			return err
197		}
198		opts.Extra = &t
199		return nil
200	}
201	
202	type CreateTaskBatch struct {
203		Reqs []*CreateTaskBatchItem `json:"reqs"`
204		Opts *Options               `json:"opts"`
205	}
206	
207	type CreateTaskBatchItem struct {
208		Req  *Request `json:"req"`
209		Opts *Options `json:"opts"`
210	}
