212	// DownloaderStoreConfig is the config that can restore the downloader.
213	type DownloaderStoreConfig struct {
214		FirstLoad bool `json:"-"` // FirstLoad is the flag that the config is first time init and not from store
215	
216		DownloadDir                string                 `json:"downloadDir"`    // DownloadDir is the default directory to save the downloaded files
217		MaxRunning                 int                    `json:"maxRunning"`     // MaxRunning is the max running download count
218		ProtocolConfig             map[string]any         `json:"protocolConfig"` // ProtocolConfig is special config for each protocol
219		GithubMirror               *GithubMirrorConfig    `json:"githubMirror"`
220		Extra                      map[string]any         `json:"extra"`
221		Proxy                      *DownloaderProxyConfig `json:"proxy"`
222		Webhook                    *WebhookConfig         `json:"webhook"`                    // Webhook is the webhook configuration
223		Script                     *ScriptConfig          `json:"script"`                     // Script is the script execution configuration
224		AutoTorrent                *AutoTorrentConfig     `json:"autoTorrent"`                // AutoTorrent is the auto torrent task creation configuration
225		Archive                    *ArchiveConfig         `json:"archive"`                    // Archive is the archive extraction configuration
226		Categories                 []*DownloadCategory    `json:"categories"`                 // Categories is the download directory category configuration
227		AutoCategorize             *bool                  `json:"autoCategorize,omitempty"`   // AutoCategorize routes downloads to category directories by file extension; unset defaults to disabled
228		API                        *APIServerConfig       `json:"api"`                        // API is the optional REST server configuration
229		AutoStartTasks             bool                   `json:"autoStartTasks"`             // AutoStartTasks continues all unfinished tasks when the backend starts
230		AutoDeleteMissingFileTasks bool                   `json:"autoDeleteMissingFileTasks"` // AutoDeleteMissingFileTasks enables automatic deletion of tasks with missing files
231	}
232	
233	func (cfg *DownloaderStoreConfig) Init() *DownloaderStoreConfig {
234		if cfg.MaxRunning == 0 {
235			cfg.MaxRunning = 5
236		}
237		if cfg.ProtocolConfig == nil {
238			cfg.ProtocolConfig = make(map[string]any)
239		}
240		if cfg.GithubMirror == nil {
241			cfg.GithubMirror = DefaultGithubMirrorConfig()
242		}
243		if cfg.Proxy == nil {
244			cfg.Proxy = &DownloaderProxyConfig{}
245		}
246		if cfg.Webhook == nil {
247			cfg.Webhook = &WebhookConfig{}
248		}
249		if cfg.Script == nil {
250			cfg.Script = &ScriptConfig{}
251		}
252		if cfg.AutoTorrent == nil {
253			cfg.AutoTorrent = &AutoTorrentConfig{
254				Enable:              false,
255				DeleteAfterDownload: false,
256			}
257		}
258		if cfg.Archive == nil {
259			cfg.Archive = &ArchiveConfig{
260				AutoExtract:        false,
261				DeleteAfterExtract: false,
262			}
263		}
264		// Seed the built-in categories for deployments that never run the flutter
265		// startup flow, e.g. headless api servers.
266		if len(cfg.Categories) == 0 && cfg.DownloadDir != "" {
267			cfg.Categories = []*DownloadCategory{
268				builtinSeedCategory("categoryMusic", "Music", cfg.DownloadDir),
269				builtinSeedCategory("categoryVideo", "Video", cfg.DownloadDir),
270				builtinSeedCategory("categoryDocument", "Document", cfg.DownloadDir),
271				builtinSeedCategory("categoryProgram", "Program", cfg.DownloadDir),
272			}
273		}
274		return cfg
275	}
276	
277	// builtinCategoryExtensions mirrors the flutter side
278	// kDefaultCategoryExtensions, keep both maps in sync.
279	var builtinCategoryExtensions = map[string][]string{
280		"categoryProgram":  {"exe", "msi", "msix", "apk", "dmg", "deb", "rpm", "pkg", "appimage"},
281		"categoryVideo":    {"mp4", "mkv", "avi", "mov", "wmv", "flv", "webm", "m4v", "mpg", "mpeg", "3gp"},
282		"categoryMusic":    {"mp3", "flac", "wav", "aac", "ogg", "m4a", "wma", "ape"},
283		"categoryDocument": {"pdf", "doc", "docx", "xls", "xlsx", "ppt", "pptx", "txt", "md", "csv", "epub", "rtf"},
284	}
285	
286	func builtinSeedCategory(nameKey, name, downloadDir string) *DownloadCategory {
287		return &DownloadCategory{
288			Name:       "",
289			Path:       filepath.Join(downloadDir, name),
290			NameKey:    nameKey,
291			IsBuiltIn:  true,
292			Extensions: append([]string(nil), builtinCategoryExtensions[nameKey]...),
293		}
294	}
295	
296	// MigrateLegacyExtraCategories moves the extra.downloadCategories list written
297	// by v2.0.0-beta builds into the top level categories field and clears the
298	// legacy key. The legacy list predates extension based routing, so built-in
299	// entries regain their default extension lists from their name key, while user
300	// created folders keep their empty list until edited in settings. It reports
301	// whether the config changed so the caller can persist the cleared key.
302	func (cfg *DownloaderStoreConfig) MigrateLegacyExtraCategories() bool {
303		if len(cfg.Categories) > 0 || cfg.Extra == nil {
304			return false
305		}
306		raw, ok := cfg.Extra["downloadCategories"]
307		if !ok {
308			return false
309		}
310		data, err := json.Marshal(raw)
311		if err != nil {
312			return false
313		}
314		var legacy []*DownloadCategory
315		if err := json.Unmarshal(data, &legacy); err != nil {
316			return false
317		}
318		categories := make([]*DownloadCategory, 0, len(legacy))
319		for _, category := range legacy {
320			if category == nil {
321				continue
322			}
323			if extensions, exist := builtinCategoryExtensions[category.NameKey]; exist && len(category.Extensions) == 0 {
324				category.Extensions = append([]string(nil), extensions...)
325			}
326			categories = append(categories, category)
327		}
328		if len(categories) == 0 {
329			return false
330		}
331		cfg.Categories = categories
332		delete(cfg.Extra, "downloadCategories")
333		return true
334	}
335	
336	// AutoCategorizeEnabled reports whether downloads are routed to category
337	// directories by file extension. The switch is optional: an unset value keeps
338	// the feature off, so an older config that never saved the field stays off.
339	func (cfg *DownloaderStoreConfig) AutoCategorizeEnabled() bool {
340		return cfg.AutoCategorize != nil && *cfg.AutoCategorize
341	}
342	
343	func (cfg *DownloaderStoreConfig) Merge(beforeCfg *DownloaderStoreConfig) *DownloaderStoreConfig {
344		if beforeCfg == nil {
345			return cfg
346		}
347		if cfg.DownloadDir == "" {
348			cfg.DownloadDir = beforeCfg.DownloadDir
349		}
350		if cfg.MaxRunning == 0 {
351			cfg.MaxRunning = beforeCfg.MaxRunning
352		}
353		if cfg.ProtocolConfig == nil {
354			cfg.ProtocolConfig = beforeCfg.ProtocolConfig
355		}
356		if cfg.Extra == nil {
357			cfg.Extra = beforeCfg.Extra
358		}
359		if cfg.GithubMirror == nil {
360			cfg.GithubMirror = beforeCfg.GithubMirror
361		}
362		if cfg.Proxy == nil {
363			cfg.Proxy = beforeCfg.Proxy
364		}
365		if cfg.Webhook == nil {
366			cfg.Webhook = beforeCfg.Webhook
367		}
368		if cfg.Script == nil {
369			cfg.Script = beforeCfg.Script
370		}
371		if cfg.AutoTorrent == nil {
372			cfg.AutoTorrent = beforeCfg.AutoTorrent
373		}
374		if cfg.Archive == nil {
375			cfg.Archive = beforeCfg.Archive
376		}
377		if cfg.Categories == nil {
378			cfg.Categories = beforeCfg.Categories
379		}
380		if cfg.AutoCategorize == nil {
381			cfg.AutoCategorize = beforeCfg.AutoCategorize
382		}
383		if cfg.API == nil {
384			cfg.API = beforeCfg.API
385		}
386		return cfg
387	}
388	
389	type APIServerConfig struct {
390		Enable    bool   `json:"enable"`
391		MCPEnable bool   `json:"mcpEnable"`
392		Network   string `json:"network"`
393		Address   string `json:"address"`
394		Token     string `json:"token"`
395	}
396	
397	func (cfg *APIServerConfig) Init() *APIServerConfig {
398		if cfg.Network == "" {
399			cfg.Network = "tcp"
400		}
401		if cfg.Address == "" {
402			cfg.Address = "127.0.0.1:9999"
403		}
404		return cfg
405	}
406	
407	// WebhookConfig is the webhook configuration
408	type WebhookConfig struct {
409		Enable bool     `json:"enable"` // Enable is the flag to enable/disable webhooks
410		URLs   []string `json:"urls"`   // URLs is the list of webhook URLs
411	}
412	
413	// ScriptConfig is the script execution configuration
414	type ScriptConfig struct {
415		Enable bool     `json:"enable"` // Enable is the flag to enable/disable script execution
416		Paths  []string `json:"paths"`  // Paths is the list of script paths to execute
417	}
418	
419	// AutoTorrentConfig is the auto torrent task creation configuration
420	type AutoTorrentConfig struct {
421		Enable              bool `json:"enable"`              // Enable enables automatic BT task creation when downloading .torrent files
422		DeleteAfterDownload bool `json:"deleteAfterDownload"` // DeleteAfterDownload deletes the .torrent file after BT task creation
423	}
424	
425	// ArchiveConfig is the archive extraction configuration
426	type ArchiveConfig struct {
427		AutoExtract        bool `json:"autoExtract"`        // AutoExtract enables automatic extraction of archives after download
428		DeleteAfterExtract bool `json:"deleteAfterExtract"` // DeleteAfterExtract deletes the archive after successful extraction
429	}
430	
431	// DownloadCategory is a download directory category that files can be routed to by extension
432	type DownloadCategory struct {
433		Name       string   `json:"name"`                 // Name is the category display name, empty for built-in categories that use NameKey
434		Path       string   `json:"path"`                 // Path is the download directory of the category
435		NameKey    string   `json:"nameKey,omitempty"`    // NameKey is the i18n key of the built-in category name
436		IsBuiltIn  bool     `json:"isBuiltIn,omitempty"`  // IsBuiltIn marks the category as built-in
437		IsDeleted  bool     `json:"isDeleted,omitempty"`  // IsDeleted marks the built-in category as deleted
438		Extensions []string `json:"extensions,omitempty"` // Extensions is the file extension list routed to the category, without leading dots
439	}
440	
441	type DownloaderProxyConfig struct {
442		Enable bool `json:"enable"`
443		// System is the flag that use system proxy
444		System bool   `json:"system"`
445		Scheme string `json:"scheme"`
446		Host   string `json:"host"`
447		Usr    string `json:"usr"`
448		Pwd    string `json:"pwd"`
449	}
450	
451	func (cfg *DownloaderProxyConfig) ToHandler() func(r *http.Request) (*url.URL, error) {
452		if cfg == nil || cfg.Enable == false {
453			return nil
454		}
455		if cfg.System {
456			safeProxyReloadConf()
457			return ieproxy.GetProxyFunc()
458		}
459		if cfg.Scheme == "" || cfg.Host == "" {
460			return nil
461		}
462		return http.ProxyURL(util.BuildProxyUrl(cfg.Scheme, cfg.Host, cfg.Usr, cfg.Pwd))
463	}
464	
465	// ToUrl returns the proxy url, just for git clone
466	func (cfg *DownloaderProxyConfig) ToUrl() *url.URL {
467		if cfg == nil || cfg.Enable == false {
468			return nil
469		}
470		if cfg.System {
471			safeProxyReloadConf()
472			static := ieproxy.GetConf().Static
473			if static.Active && len(static.Protocols) > 0 {
474				// If only one protocol, use it
475				if len(static.Protocols) == 1 {
476					for _, v := range static.Protocols {
477						return parseUrlSafe(v)
478					}
479				}
480				// Check https
481				if v, ok := static.Protocols["https"]; ok {
482					return parseUrlSafe(v)
483				}
484				// Check http
485				if v, ok := static.Protocols["http"]; ok {
486					return parseUrlSafe(v)
487				}
488			}
489			return nil
490		}
491		if cfg.Scheme == "" || cfg.Host == "" {
492			return nil
493		}
494		return util.BuildProxyUrl(cfg.Scheme, cfg.Host, cfg.Usr, cfg.Pwd)
495	}
496	
497	var prcLock sync.Mutex
498	
499	func safeProxyReloadConf() {
500		prcLock.Lock()
501		defer prcLock.Unlock()
502	
503		ieproxy.ReloadConf()
504	}
505	
506	func parseUrlSafe(rawUrl string) *url.URL {
507		u, err := url.Parse(rawUrl)
508		if err != nil {
509			return nil
510		}
511		return u
512	}
513

1	package main
2	
3	import (
4		"fmt"
5		"strings"
6		"sync"
7	
8		"github.com/GopeedLab/gopeed/internal/fetcher"
9		"github.com/GopeedLab/gopeed/pkg/base"
10		"github.com/GopeedLab/gopeed/pkg/download"
11		"github.com/GopeedLab/gopeed/pkg/protocol/http"
12		"github.com/GopeedLab/gopeed/pkg/util"
13	)
14	
15	const progressWidth = 20
16	
17	func main() {
18		args := parse()
19	
20		var wg sync.WaitGroup
21		wg.Add(1)
22		var checksumOpt *http.ChecksumOption
23		if args.checksum != nil && *args.checksum != "" {
24			algo := "md5"
25			if args.checksumAlgo != nil && *args.checksumAlgo != "" {
26				algo = *args.checksumAlgo
27			}
28			checksumOpt = &http.ChecksumOption{
29				Algorithm: algo,
30				Expected:  *args.checksum,
31			}
32		}
33	
34		_, err := download.Boot().
35			URL(args.url).
36			Listener(func(event *download.Event) {
37				if event.Key == download.EventKeyProgress {
38					printProgress(event.Task, "downloading...")
39				}
40				if event.Key == download.EventKeyFinally {
41					var title string
42					if event.Err != nil {
43						title = "fail"
44					} else {
45						title = "complete"
46					}
47					printProgress(event.Task, title)
48					fmt.Println()
49					if event.Err != nil {
50						fmt.Printf("reason: %s", event.Err.Error())
51					} else {
52						fmt.Printf("saving path: %s", *args.dir)
53					}
54					wg.Done()
55				}
56			}).
57			Create(&base.Options{
58				Path: *args.dir,
59				Extra: http.OptsExtra{
60					Connections: *args.connections,
61					Checksum:    checksumOpt,
62				},
63			})
64		if err != nil {
65			panic(err)
66		}
67		printProgress(emptyTask, "downloading...")
68		wg.Wait()
69	}
70	
71	var (
72		lastLineLen = 0
73		sb          = new(strings.Builder)
74		emptyTask   = &download.Task{
75			Progress: &download.Progress{},
76			Meta: &fetcher.FetcherMeta{
77				Res: &base.Resource{},
78			},
79		}
80	)
81	
82	func printProgress(task *download.Task, title string) {
83		var rate float64
84		if task.Meta.Res == nil {
85			task = emptyTask
86		}
87		if task.Meta.Res.Size <= 0 {
88			rate = 0
89		} else {
90			rate = float64(task.Progress.Downloaded) / float64(task.Meta.Res.Size)
91		}
92		completeWidth := int(progressWidth * rate)
93		speed := util.ByteFmt(task.Progress.Speed)
94		totalSize := util.ByteFmt(task.Meta.Res.Size)
95		sb.WriteString(fmt.Sprintf("\r%s [", title))
96		for i := 0; i < progressWidth; i++ {
97			if i < completeWidth {
98				sb.WriteString("■")
99			} else {
100				sb.WriteString("□")
101			}
102		}
103		sb.WriteString(fmt.Sprintf("] %.1f%%    %s/s    %s", rate*100, speed, totalSize))
104		if lastLineLen != 0 {
105			paddingLen := lastLineLen - sb.Len()
106			if paddingLen > 0 {
107				sb.WriteString(strings.Repeat(" ", paddingLen))
108			}
109		}
110		lastLineLen = sb.Len()
111		fmt.Print(sb.String())
112		sb.Reset()
113	}
