1	// Package nativebridge contains transport-neutral behavior shared by the
2	// Desktop C FFI and gomobile bridge adapters.
3	package nativebridge
4	
5	import (
6		"errors"
7		"fmt"
8		"sync"
9		"time"
10	
11		"github.com/GopeedLab/gopeed/pkg/rest"
12	)
13	
14	// StopTimeout bounds native shutdown even when an in-process request never returns.
15	const StopTimeout = 3 * time.Second
16	
17	var errNativeBridgeStopping = errors.New("native bridge is stopping")
18	
19	type invokeRequest struct {
20		method string
21		path   string
22		query  string
23		body   string
24	}
25	
26	type invokeTask struct {
27		id       uint64
28		request  invokeRequest
29		complete func(result string, err error)
30		once     sync.Once
31	}
32	
33	func (t *invokeTask) finish(result string, err error) {
34		t.once.Do(func() {
35			completeCallback(t.complete, result, err)
36		})
37	}
38	
39	// InvokeAsync starts an in-process API request and completes it through the
40	// supplied callback. Desktop and mobile adapters share this executor.
41	func InvokeAsync(method, path, query, body string, callback func(result string, err error)) {
42		if callback == nil {
43			return
44		}
45		task := invokeTask{
46			request: invokeRequest{
47				method: method,
48				path:   path,
49				query:  query,
50				body:   body,
51			},
52			complete: callback,
53		}
54		if !getInvokeExecutor().submit(task) {
55			completeCallback(callback, "", errNativeBridgeStopping)
56		}
57	}
58	
59	// ResumeInvokes enables request submission after the native runtime starts.
60	func ResumeInvokes() {
61		getInvokeExecutor().resume()
62	}
63	
64	// PauseInvokesAndWait prevents new submissions and gives running requests a
65	// bounded opportunity to finish before a native runtime is stopped.
66	// Requests still pending after StopTimeout are failed and detached so shutdown
67	// can continue without invoking their callbacks a second time.
68	func PauseInvokesAndWait() bool {
69		return getInvokeExecutor().pauseAndWait(StopTimeout)
