11		"github.com/GopeedLab/gopeed/pkg/rest"
12	)
13	
14	// StopTimeout bounds native shutdown even when an in-process request never returns.
15	const StopTimeout = 3 * time.Second
16	
17	var errNativeBridgeStopping = errors.New("native bridge is stopping")
18	
19	type invokeRequest struct {
20		method string
21		path   string
22		query  string
23		body   string
24	}
25	
26	type invokeTask struct {
27		id       uint64
28		request  invokeRequest
29		complete func(result string, err error)
30		once     sync.Once
31	}
32	
33	func (t *invokeTask) finish(result string, err error) {
34		t.once.Do(func() {
35			completeCallback(t.complete, result, err)
36		})
37	}
38	
39	// InvokeAsync starts an in-process API request and completes it through the
40	// supplied callback. Desktop and mobile adapters share this executor.
41	func InvokeAsync(method, path, query, body string, callback func(result string, err error)) {
42		if callback == nil {
43			return
44		}
45		task := invokeTask{
46			request: invokeRequest{
47				method: method,
48				path:   path,
49				query:  query,
50				body:   body,
51			},
52			complete: callback,
53		}
54		if !getInvokeExecutor().submit(task) {
55			completeCallback(callback, "", errNativeBridgeStopping)
56		}
57	}
58	
59	// ResumeInvokes enables request submission after the native runtime starts.
60	func ResumeInvokes() {
61		getInvokeExecutor().resume()
62	}
63	
64	// PauseInvokesAndWait prevents new submissions and gives running requests a
65	// bounded opportunity to finish before a native runtime is stopped.
66	// Requests still pending after StopTimeout are failed and detached so shutdown
67	// can continue without invoking their callbacks a second time.
68	func PauseInvokesAndWait() bool {
69		return getInvokeExecutor().pauseAndWait(StopTimeout)
70	}
71	
72	// Stop pauses native requests and shuts down the shared runtime, but never
73	// keeps the host application waiting longer than StopTimeout. Cleanup that
74	// cannot finish within the deadline is allowed to continue in the background.
75	func Stop() {
76		stopWithin(getInvokeExecutor(), rest.Stop, StopTimeout)
77	}
78	
79	func stopWithin(executor *invokeExecutor, cleanup func(), timeout time.Duration) {
80		deadline := time.Now().Add(timeout)
81		executor.pauseAndWait(time.Until(deadline))
82	
83		stopped := make(chan struct{})
84		go func() {
85			defer close(stopped)
86			cleanup()
87		}()
88	
89		remaining := time.Until(deadline)
90		if remaining <= 0 {
91			return
92		}
93		timer := time.NewTimer(remaining)
94		defer timer.Stop()
95		select {
96		case <-stopped:
97		case <-timer.C:
98		}
99	}
100	
101	var (
102		invokeExecutorOnce sync.Once
103		sharedInvoker      *invokeExecutor
104	)
105	
106	func getInvokeExecutor() *invokeExecutor {
107		invokeExecutorOnce.Do(func() {
108			sharedInvoker = newInvokeExecutor(func(request invokeRequest) string {
109				return rest.Dispatch(request.method, request.path, request.query, request.body)
110			})
111		})
112		return sharedInvoker
113	}
114	
115	// invokeExecutor starts every native API request in its own goroutine, matching
116	// net/http's request concurrency. It only tracks them to support bounded drain
117	// during shutdown; one stuck request must never prevent another from starting.
118	type invokeExecutor struct {
119		mu        sync.Mutex
120		closed    bool
121		accepting bool
122		nextID    uint64
123		pending   map[uint64]*invokeTask
124		drained   chan struct{}
125		running   sync.WaitGroup
126		handler   func(invokeRequest) string
127	}
128	
129	func newInvokeExecutor(handler func(invokeRequest) string) *invokeExecutor {
130		drained := make(chan struct{})
131		close(drained)
132		return &invokeExecutor{
133			handler:   handler,
134			accepting: true,
135			pending:   make(map[uint64]*invokeTask),
136			drained:   drained,
137		}
138	}
139	
140	func (e *invokeExecutor) submit(task invokeTask) bool {
141		e.mu.Lock()
142		if e.closed || !e.accepting {
143			e.mu.Unlock()
144			return false
145		}
146		if len(e.pending) == 0 {
147			e.drained = make(chan struct{})
148		}
149		taskID := e.nextID
150		e.nextID++
151		task.id = taskID
152		taskPtr := &task
153		e.pending[taskID] = taskPtr
154		e.running.Add(1)
155		e.mu.Unlock()
156	
157		go e.run(taskPtr)
158		return true
159	}
160	
161	func (e *invokeExecutor) resume() {
162		e.mu.Lock()
163		e.accepting = true
164		e.mu.Unlock()
165	}
166	
167	func (e *invokeExecutor) pauseAndWait(timeout time.Duration) bool {
168		e.mu.Lock()
169		e.accepting = false
170		if len(e.pending) == 0 {
171			e.mu.Unlock()
172			return true
173		}
174		drained := e.drained
175		e.mu.Unlock()
176	
177		timer := time.NewTimer(timeout)
178		defer timer.Stop()
179		select {
180		case <-drained:
181			return true
182		case <-timer.C:
183		}
184	
185		e.mu.Lock()
186		if len(e.pending) == 0 {
187			e.mu.Unlock()
188			return true
189		}
190		pending := make([]*invokeTask, 0, len(e.pending))
191		for _, task := range e.pending {
192			pending = append(pending, task)
193		}
194		e.pending = make(map[uint64]*invokeTask)
195		close(e.drained)
196		e.mu.Unlock()
197	
198		for _, task := range pending {
199			task.finish("", errNativeBridgeStopping)
200		}
201		return false
202	}
203	
204	func (e *invokeExecutor) close() {
205		e.mu.Lock()
206		e.closed = true
207		e.accepting = false
208		e.mu.Unlock()
209		e.running.Wait()
210	}
211	
212	func (e *invokeExecutor) run(task *invokeTask) {
213		defer e.running.Done()
214		result, err := e.execute(task.request)
215		task.finish(result, err)
216		e.mu.Lock()
217		if _, exists := e.pending[task.id]; exists {
218			delete(e.pending, task.id)
219			if len(e.pending) == 0 {
220				close(e.drained)
221			}
222		}
223		e.mu.Unlock()
224	}
225	
226	func (e *invokeExecutor) execute(request invokeRequest) (result string, err error) {
227		defer func() {
228			if recovered := recover(); recovered != nil {
229				err = fmt.Errorf("invoke panic: %v", recovered)
230			}
231		}()
232		return e.handler(request), nil
233	}
234	
235	func completeCallback(callback func(string, error), result string, err error) {
236		defer func() {
237			_ = recover()
238		}()
239		callback(result, err)
240	}
