25	var polyfillScript string
26	
27	type Engine struct {
28		loop *eventloop.EventLoop
29	
30		closeOnce sync.Once
31		cleanupMu sync.Mutex
32		cleanups  []func()
33	
34		Runtime *goja.Runtime
35	}
36	
37	type JSFunction func(goja.FunctionCall) goja.Value
38	
39	// RunString executes the script and returns the go type value
40	// if script result is promise, it will be resolved
41	func (e *Engine) RunString(script string) (value any, err error) {
42		return e.runOnLoop(func(runtime *goja.Runtime) (goja.Value, error) {
43			return runtime.RunString(script)
44		})
45	}
46	
47	// CallFunction calls the function and returns the go type value
48	// if function result is promise, it will be resolved
49	func (e *Engine) CallFunction(fn any, args ...any) (value any, err error) {
50		return e.runOnLoop(func(runtime *goja.Runtime) (goja.Value, error) {
51			var jsArgs []goja.Value
52			for _, arg := range args {
53				jsArgs = append(jsArgs, runtime.ToValue(arg))
54			}
55			switch f := fn.(type) {
56			case goja.Callable:
57				if args == nil {
58					return f(nil)
59				}
60				return f(nil, jsArgs...)
61			case JSFunction:
62				return callExportedFunction(func(call goja.FunctionCall) goja.Value {
63					return f(call)
64				}, jsArgs...)
65			default:
66				return nil, fmt.Errorf("unsupported function type: %T", fn)
67			}
68		})
69	}
70	
71	func (e *Engine) runOnLoop(fn func(runtime *goja.Runtime) (goja.Value, error)) (any, error) {
72		type result struct {
73			value any
74			err   error
75		}
76		ch := make(chan result, 1)
77		ok := e.loop.RunOnLoop(func(runtime *goja.Runtime) {
78			var once sync.Once
79			sendResult := func(res result) {
80				once.Do(func() {
81					ch <- res
82				})
83			}
84			defer func() {
85				if r := recover(); r != nil {
86					switch v := r.(type) {
87					case error:
88						sendResult(result{err: v})
89					case goja.Value:
90						sendResult(result{err: exportJSError(v)})
91					default:
92						sendResult(result{err: fmt.Errorf("panic: %v", r)})
93					}
94				}
95			}()
96			value, err := fn(runtime)
97			if err != nil {
98				sendResult(result{err: err})
99				return
100			}
101			if p, ok := value.Export().(*goja.Promise); ok {
102				switch p.State() {
103				case goja.PromiseStateFulfilled:
104					sendResult(result{value: exportJSValue(p.Result())})
105					return
106				case goja.PromiseStateRejected:
107					sendResult(result{err: exportJSError(p.Result())})
108					return
109				}
110				promiseObj := value.ToObject(runtime)
111				thenVal := promiseObj.Get("then")
112				thenFn, ok := goja.AssertFunction(thenVal)
113				if !ok {
114					sendResult(result{err: errors.New("promise.then is not callable")})
115					return
116				}
117				onFulfilled := runtime.ToValue(func(call goja.FunctionCall) goja.Value {
118					sendResult(result{value: exportJSValue(call.Argument(0))})
119					return goja.Undefined()
120				})
121				onRejected := runtime.ToValue(func(call goja.FunctionCall) goja.Value {
122					sendResult(result{err: exportJSError(call.Argument(0))})
123					return goja.Undefined()
124				})
125				if _, err := thenFn(promiseObj, onFulfilled, onRejected); err != nil {
126					sendResult(result{err: err})
127				}
128				return
129			}
130			sendResult(result{value: exportJSValue(value)})
131		})
132		if !ok {
133			return nil, errors.New("engine loop terminated")
134		}
135		res := <-ch
136		if res.err != nil {
137			return nil, res.err
138		}
139		return res.value, nil
140	}
141	
142	func (e *Engine) Close() {
143		e.closeOnce.Do(func() {
144			e.cleanupMu.Lock()
145			cleanups := e.cleanups
146			e.cleanups = nil
147			e.cleanupMu.Unlock()
148			for _, cleanup := range cleanups {
149				cleanup()
150			}
151			e.loop.Terminate()
152		})
153	}
