155	func (e *Engine) addCleanup(cleanup func()) {
156		if cleanup == nil {
157			return
158		}
159		e.cleanupMu.Lock()
160		e.cleanups = append(e.cleanups, cleanup)
161		e.cleanupMu.Unlock()
162	}
