177		loop := eventloop.NewEventLoop()
178		engine := &Engine{
179			loop: loop,
180		}
181		loop.Start()
182		done := make(chan struct{})
183		loop.RunOnLoop(func(runtime *goja.Runtime) {
184			defer close(done)
185			engine.Runtime = runtime
186			runtime.SetFieldNameMapper(goja.TagFieldNameMapper("json", true))
187			vm.Enable(runtime)
188			gojaurl.Enable(runtime)
189			if err := gojaerror.Enable(runtime); err != nil {
190				return
191			}
192			if err := file.Enable(runtime); err != nil {
193				return
194			}
195			if _, err := runtime.RunString(polyfillScript); err != nil {
196				return
197			}
198			// polyfill global
199			if err := runtime.Set("global", runtime.GlobalObject()); err != nil {
200				return
201			}
202			// polyfill window
203			if err := runtime.Set("window", runtime.GlobalObject()); err != nil {
204				return
205			}
206			// polyfill window.location
207			if _, err := runtime.RunString("global.location = new URL('http://localhost');"); err != nil {
208				return
209			}
210			producers := &production.Registry{}
211			streamCfg := stream.Config{}
212			if cfg.StreamConfig != nil {
213				streamCfg = *cfg.StreamConfig
214			}
215			streamCfg.Producers = producers
216			if err := stream.Enable(runtime, loop, &streamCfg); err != nil {
217				return
218			}
219			if err := ffmpegapi.Enable(runtime, loop, &ffmpegapi.Config{
220				Producers:        producers,
221				TempDir:          cfg.TempDir,
222				TempFiles:        cfg.TempFiles,
223				ProxyHandler:     cfg.ProxyConfig.ToHandler(),
224				DefaultUserAgent: cfg.HTTPUserAgent,
225				RegisterCleanup:  engine.addCleanup,
226			}); err != nil {
227				return
228			}
229			if err := fetchapi.Enable(runtime, loop, &fetchapi.Config{
230				ProxyHandler:     cfg.ProxyConfig.ToHandler(),
231				DefaultUserAgent: cfg.HTTPUserAgent,
232				RegisterCleanup:  engine.addCleanup,
233			}); err != nil {
234				return
235			}
236			if err := xhr.Enable(runtime); err != nil {
237				return
238			}
239			return
240		})
241		<-done
242		return engine
243	}
244	
245	func Run(script string) (value any, err error) {
246		engine := NewEngine(nil)
247		return engine.RunString(script)
248	}
249	
250	func exportJSValue(value goja.Value) any {
251		if value == nil {
252			return nil
253		}
254		return value.Export()
255	}
256	
257	func exportJSError(value goja.Value) error {
258		if value == nil || goja.IsUndefined(value) || goja.IsNull(value) {
259			return errors.New("promise rejected")
260		}
261		if err, ok := value.Export().(error); ok {
262			return err
263		}
264		stack := value.String()
265		if ro, ok := value.(*goja.Object); ok {
266			stackVal := ro.Get("stack")
267			if stackVal != nil && stackVal.String() != "" {
268				stack = stackVal.String()
269			}
270		}
271		return errors.New(stack)
272	}
273	
274	func callExportedFunction(fn func(goja.FunctionCall) goja.Value, args ...goja.Value) (ret goja.Value, err error) {
275		defer func() {
276			if r := recover(); r != nil {
277				switch v := r.(type) {
278				case error:
279					err = v
280				case goja.Value:
281					err = exportJSError(v)
282				default:
283					err = fmt.Errorf("panic: %v", r)
284				}
285			}
286		}()
287		return fn(goja.FunctionCall{
288			This:      nil,
289			Arguments: args,
290		}), nil
291	}
292	
293	// Post queues a notification without waiting for its callback or returned promise.
294	func (e *Engine) Post(fn func(*goja.Runtime)) bool {
295		return e.loop.RunOnLoop(fn)
296	}
