			if err != nil {
				return nil, false
			}
			params[part.param] = value
			continue
		}
		if part.literal != segments[index] {
			return nil, false
		}
	}
	return params, true
}

func cleanPath(rawPath string) string {
	clean := pathpkg.Clean("/" + strings.TrimSpace(rawPath))
	if clean == "." {
		return "/"
	}
	return clean
}

